	array(
		'question_text'  => 'A client’s functioning has steadily declined for eight weeks, but the therapist continues the same treatment because it helped similar clients. No immediate emergency is present. What is the BEST next step?',
		'option_a'       => 'Continue because general evidence overrides this client’s response without additional assessment or consultation.',
		'option_b'       => 'Reassess the formulation, goals, treatment response, risk, competence needs, and level of care; consult and modify or arrange alternative care as indicated.',
