	array(
		'question_text'  => 'A therapist provides individual treatment to an adult client. The client’s spouse attends one session to provide background information.Which statement is most accurate?',
		'option_a'       => 'The spouse automatically becomes a joint client by attending the session because family status is treated as automatic authority.',
