	array(
		'question_text'  => 'A mature 14-year-old independently requests outpatient therapy. The minor reports that involving the parent would likely expose the minor to retaliation and cause the minor to stop treatment. What should the therapist do?',
		'option_a'       => 'Contact the parent immediately without discussing the concern with the minor before confirming legal authority and the permitted scope.',
